import base64
MODEL_B64=''
raw=base64.b64decode(MODEL_B64)
# Contact-isolation experiment: remove 4D/6D friction dimensions while preserving geometry, mass and actuators.
raw=raw.replace(b'condim="6"',b'condim="3"')
# Isolate floor contact by disabling robot-robot collision filtering while preserving robot-floor contacts.
raw=raw.replace(b'<geom type="capsule" priority="1" condim="3" group="3" />',b'<geom type="capsule" priority="1" condim="3" group="3" contype="1" conaffinity="0" />')
raw=raw.replace(b'<geom name="floor" type="plane"',b'<geom name="floor" contype="0" conaffinity="1" type="plane"')
open("/kaggle/working/h2_physics_only.xml","wb").write(raw)

import subprocess,sys,os,json,time,hashlib,pickle
subprocess.run([sys.executable,'-m','pip','install','-q','mujoco==3.3.7','mujoco-mjx==3.3.7','jax[cuda12]==0.5.3','optax==0.2.5'],check=True)
os.environ['JAX_ENABLE_X64']='false'
import numpy as np,mujoco,jax,jax.numpy as jnp,optax
from jax import lax
from mujoco import mjx
print('DEVICES',jax.devices(),flush=True)
XML='/kaggle/working/h2_physics_only.xml'; STEPS=25; BATCH=2; SEED=7
QP_TOL=1e-4; QV_TOL=1e-3
m=mujoco.MjModel.from_xml_path(XML)
base=mujoco.MjData(m);mujoco.mj_resetDataKeyframe(m,base,0);mujoco.mj_forward(m,base)
rng=np.random.default_rng(SEED)
Q=np.repeat(base.qpos[None],BATCH,0);V=np.repeat(base.qvel[None],BATCH,0);C=np.repeat(base.ctrl[None],BATCH,0)
# Diverse deterministic, valid initial conditions around the home keyframe.
for b in range(1,BATCH):
 Q[b,0:2]+=rng.normal(0,0.003,2); Q[b,2]+=rng.normal(0,0.002)
 V[b,0:6]+=rng.normal(0,0.003,6); V[b,6:]+=rng.normal(0,0.006,m.nv-6)
 if m.nu:C[b]+=rng.normal(0,0.002,m.nu)
# CPU oracle is intentionally case-major and completed before creating the MJX rollout.
cq=np.empty((BATCH,STEPS,m.nq));cv=np.empty((BATCH,STEPS,m.nv));ca=np.empty((BATCH,STEPS),np.int32)
for b in range(BATCH):
 d=mujoco.MjData(m);d.qpos[:]=Q[b];d.qvel[:]=V[b];d.ctrl[:]=C[b];mujoco.mj_forward(m,d)
 for t in range(STEPS):
  mujoco.mj_step(m,d);cq[b,t]=d.qpos;cv[b,t]=d.qvel
  ca[b,t]=int(np.count_nonzero(np.asarray(d.contact.dist[:d.ncon])<=0.0))
mx=mjx.put_model(m,impl='jax');ds=[]
for b in range(BATCH):
 d=mujoco.MjData(m);d.qpos[:]=Q[b];d.qvel[:]=V[b];d.ctrl[:]=C[b];mujoco.mj_forward(m,d);ds.append(mjx.put_data(m,d,impl='jax'))
bd=jax.tree_util.tree_map(lambda *xs:jnp.stack(xs),*ds)
def trajectory(d):
 def one(x,_):
  y=mjx.step(mx,x)
  active=jnp.sum(y.contact.dist<=0.0)
  return y,(y.qpos,y.qvel,active)
 return lax.scan(one,d,None,length=STEPS)
# vmap over cases, one device-resident scan across every simulation step.
run=jax.jit(jax.vmap(trajectory))
t=time.perf_counter();_,out=run(bd);jax.block_until_ready(out);cold=time.perf_counter()-t
t=time.perf_counter();_,out=run(bd);jax.block_until_ready(out);cached=time.perf_counter()-t
mq,mv,ma=map(np.asarray,out);ep=np.max(np.abs(cq-mq),2);ev=np.max(np.abs(cv-mv),2)
def cross(x,th):return [None if not np.any(a>th) else int(np.argmax(a>th)) for a in x]
passed=bool(ep.max()<=QP_TOL and ev.max()<=QV_TOL)
report={'fixture':'h2_contact_isolation_floor_only_condim3','steps':STEPS,'batch':BATCH,'duration_s':STEPS*float(m.opt.timestep),'versions':{'mujoco':mujoco.__version__,'jax':jax.__version__},'devices':[str(x) for x in jax.devices()],'model':{'nq':m.nq,'nv':m.nv,'nu':m.nu,'ngeom':m.ngeom,'xml_sha256':hashlib.sha256(open(XML,'rb').read()).hexdigest(),'isolation_change':'condim 6 -> 3 and robot self-collision filter disabled; robot-floor retained'},'solver':{'integrator':int(m.opt.integrator),'solver':int(m.opt.solver),'iterations':int(m.opt.iterations),'ls_iterations':int(m.opt.ls_iterations),'tolerance':float(m.opt.tolerance),'ls_tolerance':float(m.opt.ls_tolerance),'cone':int(m.opt.cone),'impratio':float(m.opt.impratio),'noslip_iterations':int(m.opt.noslip_iterations),'timestep':float(m.opt.timestep)},'vectorization':{'time':'jax.lax.scan','environments':'jax.vmap','host_step_loop':False},'timing':{'cold_compile_and_rollout_s':cold,'cached_rollout_s':cached,'env_steps_per_s':BATCH*STEPS/cached},'thresholds':{'max_qpos':QP_TOL,'max_qvel':QV_TOL},'qpos_error':{'max':float(ep.max()),'per_case_max':ep.max(1).tolist(),'first_cross_1e-4':cross(ep,QP_TOL)},'qvel_error':{'max':float(ev.max()),'per_case_max':ev.max(1).tolist(),'first_cross_1e-3':cross(ev,QV_TOL)},'per_step':{'qpos_max_across_cases':ep.max(0).tolist(),'qvel_max_across_cases':ev.max(0).tolist()},'contact':{'cpu_active_dist_le_0':ca.tolist(),'mjx_active_dist_le_0':ma.tolist(),'counts_equal_all_steps':bool(np.array_equal(ca,ma)),'gated':False,'note':'Active contacts use dist<=0 on both backends; counts are diagnostic and do not gate parity.'},'pass':passed}
open('/kaggle/working/h2_parity_report.json','w').write(json.dumps(report,indent=2));print('PARITY_SUMMARY',json.dumps({'pass':passed,'max_qpos':float(ep.max()),'max_qvel':float(ev.max()),'contacts_equal':bool(np.array_equal(ca,ma)),'timing':report['timing']}),flush=True)

# Stage-1 standing/balance smoke is forbidden until its independent parity gate passes.
training={'started':False,'reason':'contact-isolation diagnostic only; training intentionally disabled','environment':'minimal H2: floor, gravity, rigid contacts, actuators; no tennis apparatus'}
if False and passed:
 TRAIN_ENVS=8; HORIZON=8; UPDATES=3; LR=2e-3
 q0=jnp.asarray(base.qpos);ctrl0=jnp.asarray(base.ctrl);lo=jnp.asarray(m.actuator_ctrlrange[:,0]);hi=jnp.asarray(m.actuator_ctrlrange[:,1])
 obs_dim=m.nq+m.nv;key=jax.random.PRNGKey(19)
 params={'w':jnp.zeros((m.nu,obs_dim),jnp.float32),'b':ctrl0.astype(jnp.float32)}
 opt=optax.adam(LR);opt_state=opt.init(params)
 def reset_one(k):
  d=mjx.make_data(mx);k1,k2=jax.random.split(k);q=q0.at[0:2].add(jax.random.uniform(k1,(2,),minval=-.02,maxval=.02));v=jax.random.normal(k2,(m.nv,))*0.01
  return d.replace(qpos=q,qvel=v,ctrl=ctrl0)
 def loss_fn(p,keys):
  states=jax.vmap(reset_one)(keys)
  def one_step(ds,_):
   obs=jnp.concatenate([ds.qpos,ds.qvel],axis=-1);a=jnp.clip(obs@p['w'].T+p['b'],lo,hi);ds=ds.replace(ctrl=a);nxt=jax.vmap(lambda x:mjx.step(mx,x))(ds)
   quat=nxt.qpos[:,3:7];upright=1.0-2.0*(quat[:,1]**2+quat[:,2]**2);height=nxt.qpos[:,2]
   r=2.0*upright+jnp.exp(-20.0*(height-q0[2])**2)-1e-4*jnp.sum(a*a,axis=-1)-2.0*jnp.square(nxt.qvel[:,2])
   return nxt,r
  _,rs=lax.scan(one_step,states,None,length=HORIZON);return -jnp.mean(rs),{'reward':jnp.mean(rs),'final_reward':jnp.mean(rs[-1])}
 value_grad=jax.jit(jax.value_and_grad(loss_fn,has_aux=True));history=[];t0=time.perf_counter()
 for u in range(UPDATES):
  key,sk=jax.random.split(key);keys=jax.random.split(sk,TRAIN_ENVS);(loss,metrics),grads=value_grad(params,keys);updates,opt_state=opt.update(grads,opt_state,params);params=optax.apply_updates(params,updates);jax.block_until_ready(loss)
  history.append({'update':u+1,'loss':float(loss),'mean_reward':float(metrics['reward']),'final_reward':float(metrics['final_reward'])})
 ckpt='/kaggle/working/h2_stage1_smoke_checkpoint.pkl'
 with open(ckpt,'wb') as f:pickle.dump({'params':jax.device_get(params),'opt_state':jax.device_get(opt_state),'update':UPDATES,'history':history},f)
 # Prove that a fresh in-run load resumes and executes another optimizer update.
 with open(ckpt,'rb') as f:loaded=pickle.load(f)
 resumed_params=jax.tree_util.tree_map(jnp.asarray,loaded['params']);resumed_opt=jax.tree_util.tree_map(jnp.asarray,loaded['opt_state']);key,sk=jax.random.split(key);keys=jax.random.split(sk,TRAIN_ENVS)
 (loss,metrics),grads=value_grad(resumed_params,keys);updates,resumed_opt=opt.update(grads,resumed_opt,resumed_params);resumed_params=optax.apply_updates(resumed_params,updates);jax.block_until_ready(loss)
 resume_ckpt='/kaggle/working/h2_stage1_smoke_resumed.pkl'
 with open(resume_ckpt,'wb') as f:pickle.dump({'params':jax.device_get(resumed_params),'opt_state':jax.device_get(resumed_opt),'update':UPDATES+1},f)
 training={'started':True,'algorithm':'differentiable MJX policy-gradient smoke (PPO is the later full run)','environment':'minimal H2: floor, gravity, rigid contacts, actuators; no tennis apparatus','vectorization':{'time':'jax.lax.scan','environments':'jax.vmap','host_step_loop':False},'envs':TRAIN_ENVS,'horizon':HORIZON,'updates':UPDATES,'elapsed_s':time.perf_counter()-t0,'initial_reward':history[0]['mean_reward'],'final_reward':history[-1]['mean_reward'],'checkpoint':ckpt,'resume_checkpoint':resume_ckpt,'resume_verified_update':UPDATES+1,'history':history}
open('/kaggle/working/h2_stage1_smoke_report.json','w').write(json.dumps(training,indent=2));print('TRAINING_SUMMARY',json.dumps({k:training[k] for k in training if k!='history'}),flush=True)
